dslRule:
/*!id: add.null.check.before.method.call.in.or.condition*/
/*!description: Adds a null check for the receiver of a method call when it appears as the second operand of an OR (||) expression, preventing NullPointerException if the receiver is null. Applies only if the receiver has no side effects, and the method call is part of an equality comparison.*/
/*!severity: WARNING*/
$cond1 || $receiver.method($args$) == $comparisonValue :: hasNoSideEffect($receiver)
=>
$cond1 || $receiver != null && $receiver.method($args$) == $comparisonValue
;;

beforeExample:
import org.eclipse.core.runtime.IAdaptable;

public class TestClass {
    private Object fActivePart;
    private TestClass self = this;

    static class MyAdaptable implements IAdaptable {
        @Override
        public <T> T getAdapter(Class<T> adapter) {
            if (adapter.equals(TestClass.class)) {
                return (T) new TestClass();
            }
            return null;
        }
    }

    void someMethod() {
        if (fActivePart == self || ((IAdaptable) fActivePart).getAdapter(TestClass.class) == self) {
            System.out.println("Matched");
        }

        MyAdaptable myAdaptable = new MyAdaptable();
        if (myAdaptable.hashCode() == 0 || myAdaptable.getAdapter(TestClass.class) == this) {
            System.out.println("Matched again");
        }
    }

    private TestClass getTestClass() { return this; }
    private Object getPotentiallyNullObject() { return null; }

    void sideEffectMethod() {
        if (true || getPotentiallyNullObject().hashCode() == 0) {
        }
    }
}

