negativeExample:
import org.eclipse.core.runtime.IAdaptable;

public class TestClass {
    private Object fActivePart;
    private TestClass self = this;

    static class MyAdaptable implements IAdaptable {
        @Override
        public <T> T getAdapter(Class<T> adapter) {
            if (adapter.equals(TestClass.class)) {
                return (T) new TestClass();
            }
            return null;
        }
    }

    void someMethod() {
        // Already has the null check
        if (fActivePart == self || fActivePart != null && ((IAdaptable) fActivePart).getAdapter(TestClass.class) == self) {
            System.out.println("Already handled");
        }
        // Not in an OR condition
        if (((IAdaptable) fActivePart).getAdapter(TestClass.class) == self) {
            System.out.println("Not an OR");
        }
        // Method call not followed by ==
        if (fActivePart == self || ((IAdaptable) fActivePart).getAdapter(TestClass.class) != null) {
            System.out.println("Not == comparison");
        }
        // Receiver has side effects - should not match due to guard
        if (fActivePart == self || getPotentiallyNullObject().getAdapter(TestClass.class) == self) {
            System.out.println("Side effect receiver - should not match");
        }
    }

    private Object getPotentiallyNullObject() {
        System.out.println("Calling getPotentiallyNullObject");
        return null;
    }
}
